#include <stdio.h>
int main(void) {
    int a[3] = {1, 3, 5}, b[3] = {2, 4, 6}, c[6];
    int i = 0, j = 0, k = 0;
    while (i < 3 && j < 3) c[k++] = (a[i] < b[j]) ? a[i++] : b[j++];
    while (i < 3) c[k++] = a[i++];
    while (j < 3) c[k++] = b[j++];
    printf("%d %d %d %d %d %d\n", c[0], c[1], c[2], c[3], c[4], c[5]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {4, 1, 3, 5, 2}, pivot = a[4], i = -1;
    for (int j = 0; j < 4; j++)
        if (a[j] < pivot) { i++; int t = a[i]; a[i] = a[j]; a[j] = t; }
    int t = a[i+1]; a[i+1] = a[4]; a[4] = t;
    printf("%d\n", i + 1);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[6] = {7, 2, 9, 4, 3, 8};
    int pivot = a[5], i = -1;
    for (int j = 0; j < 5; j++)
        if (a[j] < pivot) { i++; int t = a[i]; a[i] = a[j]; a[j] = t; }
    int t = a[i+1]; a[i+1] = a[5]; a[5] = t;
    printf("%d %d %d %d %d %d\n", a[0], a[1], a[2], a[3], a[4], a[5]);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[5] = {1, 2, 3, 4, 5}, pivot = a[4], i = -1;
    for (int j = 0; j < 4; j++)
        if (a[j] < pivot) { i++; int t = a[i]; a[i] = a[j]; a[j] = t; }
    printf("%d %d\n", i + 1, 4 - (i + 1));
    return 0;
}

