#include <stdio.h>
int calls = 0;
void msort(int n) {
    calls++;
    if (n <= 1) return;
    msort(n / 2);
    msort(n - n / 2);
}
int main(void) { msort(4); printf("%d\n", calls); return 0; }

#include <stdio.h>
int main(void) {
    int a[3] = {1, 4, 7}, b[3] = {2, 3, 9}, cmp = 0;
    int i = 0, j = 0;
    while (i < 3 && j < 3) {
        cmp++;
        if (a[i] < b[j]) i++; else j++;
    }
    printf("%d\n", cmp);
    return 0;
}
